package com.example.auth.service;

import com.example.auth.entity.AccessToken;
import com.example.auth.entity.OneTimeToken;
import com.example.auth.entity.RefreshToken;
import com.example.auth.repository.AccessTokenRepository;
import com.example.auth.repository.OneTimeTokenRepository;
import com.example.auth.repository.RefreshTokenRepository;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;
import java.util.UUID;

@Service
public class AuthService {

    @Autowired
    private AccessTokenRepository accessTokenRepository;

    @Autowired
    private RefreshTokenRepository refreshTokenRepository;

    @Autowired
    private OneTimeTokenRepository oneTimeTokenRepository;

    private static final long ACCESS_TOKEN_EXPIRY_SECONDS = 10 * 60; // 10 minutes
    private static final long REFRESH_TOKEN_EXPIRY_SECONDS = 24 * 60 * 60; // 24 hours
    private static final long ONETIME_TOKEN_EXPIRY_SECONDS = 5 * 60; // 5 minutes

    public LoginResponse login(String username, String password) {
        // Accept any non-empty username and password combination - no validation needed
        if (username == null || username.trim().isEmpty() || password == null || password.trim().isEmpty()) {
            return null; // Will be handled by controller with 400
        }

        String accessToken = generateToken("ACCESS");
        String refreshToken = generateToken("REFRESH");
        String oneTimeToken = generateToken("ONETIME");

        // Store all tokens atomically
        AccessToken access = new AccessToken();
        access.setTokenValue(accessToken);
        access.setUserId(username);
        access.setTokenType("ACCESS");
        access.setIssuedAt(LocalDateTime.now());
        access.setExpiresAt(LocalDateTime.now().plusMinutes(ACCESS_TOKEN_EXPIRY_SECONDS));
        access.setIsRevoked(false);
        accessTokenRepository.save(access);

        RefreshToken refresh = new RefreshToken();
        refresh.setTokenValue(refreshToken);
        refresh.setUserId(username);
        refresh.setTokenType("REFRESH");
        refresh.setIssuedAt(LocalDateTime.now());
        refresh.setExpiresAt(LocalDateTime.now().plusHours(REFRESH_TOKEN_EXPIRY_SECONDS));
        refresh.setIsRevoked(false);
        refreshTokenRepository.save(refresh);

        OneTimeToken oneTime = new OneTimeToken();
        oneTime.setTokenValue(oneTimeToken);
        oneTime.setUserId(username);
        oneTime.setTokenType("ONETIME");
        oneTime.setIssuedAt(LocalDateTime.now());
        oneTime.setExpiresAt(LocalDateTime.now().plusMinutes(ONETIME_TOKEN_EXPIRY_SECONDS));
        oneTime.setIsRevoked(false);
        oneTime.setIsConsumed(false);
        oneTimeTokenRepository.save(oneTime);

        return new LoginResponse(accessToken, oneTimeToken, refreshToken);
    }

    private String generateToken(String type) {
        // Generate a random token string
        return UUID.randomUUID().toString();
    }

    public class LoginResponse {
        public String accessToken;
        public String oneTimeToken;
