    private static final long ONETIME_TOKEN_EXPIRY_SECONDS = 5 * 60; // 5 minutes

    // Login
    @Transactional
    public Map<String, Object> login(String username, String password) {
        if (username == null || username.trim().isEmpty() || password == null || password.trim().isEmpty()) {
            throw new IllegalArgumentException("Username and password must be non-empty");
        }

        String accessToken = generateToken();
        String refreshToken = generateToken();
        String oneTimeToken = generateToken();

        AccessToken access = new AccessToken();
        access.setTokenValue(accessToken);
        access.setUserId(username);
        access.setTokenType("ACCESS");
        access.setIssuedAt(LocalDateTime.now());
        access.setExpiresAt(LocalDateTime.now().plusMinutes(ACCESS_TOKEN_EXPIRY_SECONDS));
        access.setIsRevoked(false);
        accessTokenRepository.save(access);

        RefreshToken refresh = new RefreshToken();
        refresh.setTokenValue(refreshToken);
        refresh.setUserId(username);
        refresh.setTokenType("REFRESH");
        refresh.setIssuedAt(LocalDateTime.now());
        refresh.setExpiresAt(LocalDateTime.now().plusHours(REFRESH_TOKEN_EXPIRY_SECONDS));
        refresh.setIsRevoked(false);
        refreshTokenRepository.save(refresh);

        OneTimeToken oneTime = new OneTimeToken();
        oneTime.setTokenValue(oneTimeToken);
        oneTime.setUserId(username);
        oneTime.setTokenType("ONETIME");
        oneTime.setIssuedAt(LocalDateTime.now());
        oneTime.setExpiresAt(LocalDateTime.now().plusMinutes(ONETIME_TOKEN_EXPIRY_SECONDS));
        oneTime.setIsRevoked(false);
        oneTime.setIsConsumed(false);
        oneTimeTokenRepository.save(oneTime);

        Map<String, Object> response = new HashMap<>();
        response.put("accessToken", accessToken);
        response.put("oneTimeToken", oneTimeToken);
        // refreshToken is not in body - it goes to cookie
        return response;
    }

    // Renew - only refresh token value is provided
    @Transactional
    public Map<String, Object> renew(String refreshTokenValue) {
        RefreshToken existing = refreshTokenRepository.findByTokenValue(refreshTokenValue).orElse(null);
        if (existing == null) {
            return Map.of("error", "Refresh token not found");
        }

        if (existing.getIsRevoked() == true) {
            return Map.of("error", "Refresh token is revoked");
        }
        if (existing.getExpiresAt().isBefore(LocalDateTime.now())) {
            return Map.of("error", "Refresh token is expired");
        }

        // Atomically revoke old and issue new ones
        existing.setIsRevoked(true);
        refreshTokenRepository.save(existing); // Updates the DB with revoked status

        String newRefreshToken = generateToken();
        String newAccessToken = generateToken();

        RefreshToken newRefresh = new RefreshToken();
        newRefresh.setTokenValue(newRefreshToken);
        newRefresh.setUserId(existing.getUserId());
        newRefresh.setTokenType("REFRESH");
        newRefresh.setIssuedAt(LocalDateTime.now());
        newRefresh.setExpiresAt(LocalDateTime.now().plusHours(REFRESH_TOKEN_EXPIRY_SECONDS));
        newRefresh.setIsRevoked(false);
        refreshTokenRepository.save(newRefresh);

        AccessToken newAccess = new AccessToken();
        newAccess.setTokenValue(newAccessToken);
        newAccess.setUserId(existing.getUserId());
        newAccess.setTokenType("ACCESS");
        newAccess.setIssuedAt(LocalDateTime.now());
        newAccess.setExpiresAt(LocalDateTime.now().plusMinutes(ACCESS_TOKEN_EXPIRY_SECONDS));
        newAccess.setIsRevoked(false);
        accessTokenRepository.save(newAccess);

        Map<String, Object> response = new HashMap<>();
        response.put("accessToken", newAccessToken);
        return response;
    }

