    @Transactional
    public Map<String, Object> logout(String accessTokenValue) {
        AccessToken access = accessTokenRepository.findByTokenValue(accessTokenValue).orElse(null);
        if (access == null) {
            return Map.of("error", "Access token not found");
        }
        if (access.getIsRevoked() == true) {
            return Map.of("error", "Access token is revoked");
        }
        if (access.getExpiresAt().isBefore(LocalDateTime.now())) {
            return Map.of("error", "Access token is expired");
        }

        String userId = access.getUserId();
        // Revoke all tokens for this user
        accessTokenRepository.revokeAllAccessTokensForUser(userId, "ACCESS");
        refreshTokenRepository.revokeAllRefreshTokensForUser(userId, "REFRESH");
        oneTimeTokenRepository.revokeAllOneTimeTokensForUser(userId, "ONETIME");

        return Map.of("message", "Logged out successfully");
    }

    // Validate token - only token value is provided
    @Transactional
    public Map<String, Object> validateToken(String tokenValue) {
        OneTimeToken token = oneTimeTokenRepository.findByTokenValue(tokenValue).orElse(null);
        if (token == null) {
            return Map.of("valid", false, "message", "Token not found");
        }

        // Also check if it matches expected token type? The requirement says it's a one-time token.
        // Let me check its tokenType is ONETIME as well.
        if (!"ONETIME".equals(token.getTokenType())) {
            return Map.of("valid", false, "message", "Invalid token type");
        }

        if (token.getIsConsumed() == true) {
            return Map.of("valid", false, "message", "Token already consumed");
        }
        if (token.getIsRevoked() == true) {
            return Map.of("valid", false, "message", "Token is revoked");
        }
        if (token.getExpiresAt().isBefore(LocalDateTime.now())) {
            return Map.of("valid", false, "message", "Token is expired");
        }

        // Valid - consume it atomically
        token.setIsConsumed(true);
        oneTimeTokenRepository.save(token);

        return Map.of("valid", true, "message", "Token validated and consumed");
    }

    private String generateToken() {
        return java.util.UUID.randomUUID().toString();
    }
}
