        String newRefreshToken = (String) response.get("refreshToken");

        Map<String, Object> body = new HashMap<>();
        body.put("accessToken", accessToken);

        // Set new refreshToken cookie
        Cookie cookie = new Cookie("refreshToken", newRefreshToken);
        cookie.setHttpOnly(true);
        cookie.setMaxAge(86400);
        cookie.setPath("/api/auth");
        response.addHeader("Set-Cookie", cookie.toString());

        return ResponseEntity.ok(body);
    }

    @PostMapping("/logout")
    public ResponseEntity<?> logout(@RequestHeader("Authorization") String authHeader) {
        if (!authHeader.startsWith("Bearer ")) {
            return ResponseEntity.status(401).body(Map.of("message", "Invalid authorization header"));
        }
        String accessToken = authHeader.substring(7);

        Map<String, Object> response = authService.logout(accessToken);
        return ResponseEntity.ok(Map.of("message", "Logged out successfully"));
    }

    @PostMapping("/validate-token")
    public ResponseEntity<?> validateToken(@RequestBody Map<String, String> request) {
        String token = request.get("token");
