            return ResponseEntity.badRequest().body(Map.of("error", "Username or password is missing"));
        }

        Map<String, Object> response = authService.login(username, password);
        String accessToken = (String) response.get("accessToken");
        String oneTimeToken = (String) response.get("oneTimeToken");
        String refreshToken = (String) response.get("refreshToken");

        Map<String, Object> body = new HashMap<>();
        body.put("accessToken", accessToken);
        body.put("oneTimeToken", oneTimeToken);

        ResponseEntity<Map> resp = ResponseEntity.ok(body);
        Cookie cookie = new Cookie("refreshToken", refreshToken);
        cookie.setHttpOnly(true);
        cookie.setMaxAge(86400);
        resp.getHeaders().add("Set-Cookie", cookie.toString());
        return resp;
    }

    @PostMapping("/renew")
    public ResponseEntity<?> renew(@CookieValue(name = "refreshToken", required = false) String cookieRefreshToken,
                                   @RequestHeader(value = "refreshToken", required = false) String headerRefreshToken) {
        String refreshToken = null;
        if (cookieRefreshToken != null && !cookieRefreshToken.isEmpty()) {
