package com.example.auth.service;

import com.example.auth.entity.AccessToken;
import com.example.auth.entity.OneTimeToken;
import com.example.auth.entity.RefreshToken;
import com.example.auth.repository.AccessTokenRepository;
import com.example.auth.repository.OneTimeTokenRepository;
import com.example.auth.repository.RefreshTokenRepository;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Service;

import java.time.LocalDateTime;
import java.util.List;

@Service
public class CleanupService {

    @Autowired
    private AccessTokenRepository accessTokenRepository;

    @Autowired
    private RefreshTokenRepository refreshTokenRepository;

    @Autowired
    private OneTimeTokenRepository oneTimeTokenRepository;

    @Scheduled(fixedRate = 10000) // Every 10 seconds
    public void cleanup() {
        long deletedCount = 0;

        // Delete expired or revoked access tokens
        List<AccessToken> accessTokens = accessTokenRepository.findAll();
        for (AccessToken token : accessTokens) {
            if (token.getIsRevoked() == true || token.getExpiresAt().isBefore(LocalDateTime.now())) {
                accessTokenRepository.deleteById(token.getId());
                deletedCount++;
            }
        }

        // Delete expired or revoked refresh tokens
        List<RefreshToken> refreshTokens = refreshTokenRepository.findAll();
        for (RefreshToken token : refreshTokens) {
            if (token.getIsRevoked() == true || token.getExpiresAt().isBefore(LocalDateTime.now())) {
                refreshTokenRepository.deleteById(token.getId());
                deletedCount++;
            }
        }

        // Delete expired, revoked, or consumed one-time tokens
        List<OneTimeToken> oneTimeTokens = oneTimeTokenRepository.findAll();
        for (OneTimeToken token : oneTimeTokens) {
            if (token.getIsRevoked() == true || token.getIsConsumed() == true || token.getExpiresAt().isBefore(LocalDateTime.now())) {
                oneTimeTokenRepository.deleteById(token.getId());
                deletedCount++;
            }
        }

        System.out.println("[CLEANUP] Deleted " + deletedCount + " tokens");
    }
}
